import { useState } from "react";
import { Card } from "@/shared/ui/data/Card";
import { Chip } from "@/shared/ui/data/Chip";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";

// Vendored from `@/shared/lib/session/sessionRoles` + `roleProfile` (unresolvable in this sandbox —
// the real ROLE_DEFAULTS table loads from a JSON asset, `@data/permissions/role-capabilities.json`).
// ROLE_PROFILE + roleProfileId are the real, verbatim pure logic; ROLE_DEFAULTS below is representative
// sample data for a subset of the real SessionRole set (the full enum has ~20 roles).
const ROLE_DEFAULTS = {
  planner:  { github: "read", git: "read", code: "none", net: "read", ui: "none", writeGlobs: ["goal.md", "phases.json", "prompts/**"] },
  worker:   { github: "write", git: "write", code: "write", net: "read", ui: "read", writeGlobs: ["src/**"] },
  director: { github: "write", git: "write", code: "none", net: "read", ui: "read", writeGlobs: [".gitignore", "package.json"] },
  triage:   { github: "read", git: "read", code: "none", net: "read", ui: "none", writeGlobs: [] },
  designer: { github: "none", git: "none", code: "none", net: "none", ui: "write", writeGlobs: [] },
};
const ROLE_PROFILE = {
  planner: "sys_planner", worker: "pf_auto", director: "pf_review", triage: "pf_review", designer: "pf_review",
};
function roleProfileId(role) {
  return ROLE_PROFILE[role] ?? "pf_sandbox";
}
// Simplified stand-in for the real `roleDeniedCommands` (launchRules.ts, deep pure derivation) —
// a role with no GitHub/git access denies the matching CLI prefixes.
function roleDeniedCommands(cap) {
  const denied = [];
  if (cap.github === "none") denied.push("gh");
  if (cap.git === "none") denied.push("git push", "git commit");
  return denied;
}

function tierTone(tier) {
  return tier === "write" ? "accent" : tier === "read" ? "info" : "neutral";
}
const AXES = [
  { key: "git", label: "git" },
  { key: "github", label: "github" },
  { key: "code", label: "code" },
  { key: "net", label: "net" },
  { key: "ui", label: "ui" },
];
function RoleRow({ role }) {
  const cap = ROLE_DEFAULTS[role];
  const [open, setOpen] = useState(false);
  const denied = roleDeniedCommands(cap);
  const scope = cap.writeGlobs.length > 0 ? cap.writeGlobs.join("  ") : "—";

  return (
    <Box border="soft" radius="sm" pad={[9, 11]}>
      <Row justify="between" align="baseline" wrap gap={8}>
        <Text mono weight={600} size={12}>{role}</Text>
        <Text mono tone="muted" size={10} title="Default permission profile launched for this role">
          {roleProfileId(role)}
        </Text>
      </Row>

      <Row gap={6} wrap style={{ marginTop: 8 }}>
        {AXES.map(({ key, label }) => (
          <Chip key={key} tone={tierTone(cap[key])} size="sm">
            {label}: {cap[key]}
          </Chip>
        ))}
      </Row>

      <Row gap={6} align="baseline" wrap style={{ marginTop: 8 }}>
        <Text tone="dim" size={10}>write-scope</Text>
        <Text mono tone={cap.writeGlobs.length > 0 ? "muted" : "dim"} size={10.5}>{scope}</Text>
      </Row>

      {denied.length > 0 && (
        <Box style={{ marginTop: 8 }}>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setOpen((v) => !v)}
            aria-expanded={open}
          >
            {open ? "Hide" : "Show"} {denied.length} denied command{denied.length === 1 ? "" : "s"}
          </Button>
          {open && (
            <Row gap={6} wrap style={{ marginTop: 8 }}>
              {denied.map((cmd) => (
                <Chip key={cmd} tone="danger" size="xs">{cmd}</Chip>
              ))}
            </Row>
          )}
        </Box>
      )}
    </Box>
  );
}
export function AgentRolesCard() {
  const roles = Object.keys(ROLE_DEFAULTS);

  return (
    <Card
      title="Agent roles"
      hint="live from the #219 role gate"
    >
      <Text as="p" tone="muted" size={12} style={{ margin: "0 0 14px", lineHeight: 1.6 }}>
        Every session launches under a <strong>role</strong> that bounds what it can do
        (least-privilege). These are the capability tiers each role is granted — <strong>git</strong>,{" "}
        <strong>github</strong>, <strong>code</strong>, <strong>net</strong>, and <strong>ui</strong> access, its
        write-scope, and the default profile it runs under.
      </Text>

      <Stack gap={8}>
        {roles.map((role) => (
          <RoleRow key={role} role={role} />
        ))}
      </Stack>
    </Card>
  );
}
